use verus::prelude::*;

verus! {

    /// Given a vector of non-empty `Vec<char>`, returns a `Vec<char>`
    /// containing the last character of each inner vector, in order.
    fn extract_rear_chars(s: &Vec<Vec<char>>) -> Vec<char>
        requires
            // Every inner sequence is non-empty
            forall|i: usize| i < s.len() ==> s[i].len() > 0,
        ensures
            // The result has the same length as the outer sequence
            result.len() == s.len(),
        ensures
            // For each index, the result element equals the last char of s[i]
            forall|i: usize| i < result.len() ==>
                result[i] == s[i][s[i].len() - 1]
    {
        // Initialize the result vector
        let mut res: Vec<char> = Vec::new();
        let mut i: usize = 0;

        // Iterate over each inner vector, pushing its last character
        while i < s.len()
            invariant
                // i never exceeds s.len()
                i <= s.len(),
            invariant
                // res.len() tracks i
                res.len() == i,
            invariant
                // For all processed indices, res[j] is the last char of s[j]
                forall|j: usize| j < i ==>
                    res[j] == s[j][s[j].len() - 1],
            decreases
                // Ensure termination
                s.len() - i
        {
            let inner = &s[i];
            let last_char = inner[inner.len() - 1];
            res.push(last_char);
            i += 1;
        }

        res
    }

}